  function displayScore() {
    fill(0);
    textSize(16);
    textAlign(CENTER);
    text(score, width/2, -10);
  }

  // Add the updateScore and displayScore functions to the draw function
  function draw() {
    // Draw the player
    player.draw();

    // Update the score
    updateScore();

    // Display the score
    displayScore();
  }
